def classify_sla_path(media_type):
    if media_type in ('text', 'image'):
        return {'mode': 'SYNC_PRE_PUBLISH', 'budget_ms': 200}
    return {'mode': 'ASYNC_KAFKA_GPU', 'budget_ms': 5000}

def ingest_upload(asset_meta, s3_key):
    if pre_filter.is_known_violation(asset_meta, s3_key):
        return {'status': 'REJECTED_TIER1'}
    kafka_producer.send('moderation.pending', {'s3_key': s3_key, 'meta': asset_meta})
    return {'status': 'ACCEPTED_FOR_SCAN'}

def adjusted_threshold(base_thresh, strikes_30d, posts_per_min):
    penalty = min(0.25, strikes_30d * 0.05 + max(0, posts_per_min - 5) * 0.02)
    return max(0.30, base_thresh - penalty)

def select_kafka_topic(is_livestream, view_velocity, report_count):
    if is_livestream or view_velocity > 100 or report_count > 3:
        return 'moderation.gpu.priority'
    return 'moderation.gpu.standard'

def submit_moderator_verdict(item_id, mod_id, decision, severity):
    audit_log.record(item_id, mod_id, decision)
    if severity == 'HIGH' and consensus_count(item_id, decision) < 2:
        return 'AWAITING_SECOND_REVIEW'
    return policy_enforcer.apply(item_id, decision)
